mapper.select:
SELECT bp.* FROM business_price AS bp INNER JOIN contract_project AS cp ON cp.id = bp.project_id INNER JOIN business_price_detail AS de ON bp.id = de.business_price_id LEFT JOIN tech_artifact AS a ON de.product_type = 2 AND de.product_id = a.id AND a.bool_delete_enum = 0 LEFT JOIN tech_enclosure AS b ON de.product_type = 4 AND de.product_id = b.id AND b.bool_delete_enum = 0 LEFT JOIN tech_standard_part AS c ON de.product_type = 8 AND de.product_id = c.id AND c.bool_delete_enum = 0 WHERE bp.bool_delete_enum = 0 AND cp.bool_delete_enum = 0 AND de.bool_delete_enum = 0 and bp.project_id in
#{projectId}
AND YEAR(cp.create_time) = YEAR(#{year})
AND bp.branch_company_id = #{branchCompanyId}
AND bp.project_id = #{projectId}
AND bp.product_type = #{productType}
AND bp.pricing_manner_enum = #{pricingMannerEnum}
AND bp.audit_status = #{auditStatus}
AND bp.pricing_name LIKE CONCAT('%', #{pricingName},'%')
and ( a.name LIKE CONCAT('%', #{name},'%') or b.name LIKE CONCAT('%', #{name},'%') or c.name LIKE CONCAT('%', #{name},'%') )
and ( a.serial_number LIKE CONCAT('%', #{serialNumber},'%') or b.serial_number LIKE CONCAT('%', #{serialNumber},'%') or c.serial_number LIKE CONCAT('%', #{serialNumber},'%') )
GROUP BY bp.id HAVING IFNULL(sum(a.quantity), 0) + IFNULL(sum(b.quantity), 0) + IFNULL(sum(c.quantity), 0) > 0 ORDER BY bp.audit_status, bp.id DESC
